<script lang="ts">
  import { defineComponent, computed } from 'vue'
  import ExceptionPage from './exception-page.vue'
  import { udpAppStore } from 'udp/store/app-store'
  import { getColorPalette } from 'udp/utils/color'
  export default defineComponent({
    name: 'PageBuilding',
    components: { ExceptionPage },
    setup() {
      const appStore = udpAppStore()
      const theme = computed(() => appStore.theme)
      const themeLighter = computed(() => getColorPalette(appStore.theme, 5))
      const themeLightest = computed(() => getColorPalette(appStore.theme, 3))
      const themeDarker = computed(() => getColorPalette(appStore.theme, 8))
      const themeDarkest = computed(() => getColorPalette(appStore.theme, 9))
      return {
        pageInfo: {
          title: 'PageBuilding',
          desc: 'm_pageBuilding'
        },
        theme,
        themeLighter,
        themeLightest,
        themeDarker,
        themeDarkest
      }
    }
  })
</script>

